def preserve_admitted_capacity(apps, schema_editor):
    """0008 had no seat limit; never invalidate existing active admissions."""
    alias = schema_editor.connection.alias
    participants = apps.get_model('learning', 'SessionParticipant')
    classrooms = apps.get_model('learning', 'Classroom')
